from math import gcd
from itertools import combinations

# Witness is embedded as constants; verifier is pure, deterministic,
# exact integer arithmetic, fail-closed, no I/O, no floats.

WITNESS_R = 3
WITNESS_F3 = [1, 2, 2, 3, 3, 3, 3]

def feasible(S, r=3):
    for T in combinations(S, r):
        g1 = gcd(T[0], T[1])
        g2 = gcd(T[0], T[2])
        g3 = gcd(T[1], T[2])
        if g1 == g2 == g3:
            return False
    return True

def f3(N):
    universe = list(range(1, N + 1))
    for size in range(N, 0, -1):
        for S in combinations(universe, size):
            if feasible(list(S)):
                return size
    raise AssertionError('unreachable: singleton always feasible')

def verify() -> bool:
    if WITNESS_R != 3:
        return False
    if len(WITNESS_F3) != 7:
        return False
    for N in range(1, 8):
        if f3(N) != WITNESS_F3[N - 1]:
            return False
    return True

RESULT = verify()
assert RESULT, 'FAIL'
